<?php defined('_JEXEC') or die; use Joomla\CMS\Router\Route; ?>
<div class="kaar-booking kaar-booking__package-grid" style="grid-template-columns:repeat(<?php echo max(1,min(4,(int)$params->get('columns',3))); ?>,minmax(0,1fr))">
<?php foreach($packages as $package): ?><article class="kaar-booking__package-card"><div class="kaar-booking__package-body"><h3><?php echo htmlspecialchars($package['title'],ENT_QUOTES,'UTF-8'); ?></h3><?php if($params->get('show_duration',1)): ?><p><strong><?php echo (int)$package['duration_days']; ?> days / <?php echo (int)$package['duration_nights']; ?> nights</strong></p><?php endif; ?><?php if($params->get('show_summary',1)): ?><p><?php echo htmlspecialchars($package['summary']??'',ENT_QUOTES,'UTF-8'); ?></p><?php endif; ?><?php if($params->get('show_details',1)): ?><details><summary>Show included items</summary><ul><?php foreach($package['items'] as $item): ?><?php if($item['item_type']==='included'): ?><li><?php echo htmlspecialchars($item['title'],ENT_QUOTES,'UTF-8'); ?></li><?php endif; ?><?php endforeach; ?></ul></details><?php endif; ?><?php if($params->get('show_price',1)): ?><p class="kaar-booking__price"><?php echo htmlspecialchars($package['currency'],ENT_QUOTES,'UTF-8').' '.number_format((float)$package['base_price'],2); ?></p><?php endif; ?></div><a class="kaar-booking__primary" href="<?php echo Route::_('index.php?option=com_kaarbooking&view=booking&package_id='.(int)$package['id']); ?>">Book</a></article><?php endforeach; ?>
<?php if(!$packages): ?><p>No packages are currently available.</p><?php endif; ?></div>
